-- Independent stores and identities for the connected training flow.
insert into auth.users(id,email,email_confirmed_at) select ('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'training'||n||'@example.test',now() from generate_series(20,27) n;
insert into public.profiles(user_id,full_name) select id,'Training user '||right(id::text,2) from auth.users where email like 'training%@example.test';
insert into public.organizations(id,name) values('10000000-0000-0000-0000-000000000020','Training Store A'),('10000000-0000-0000-0000-000000000021','Training Store B');
insert into public.organization_memberships(id,organization_id,user_id,email,role)
select ('20000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,case when n<25 then '10000000-0000-0000-0000-000000000020' else '10000000-0000-0000-0000-000000000021' end::uuid,('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'training'||n||'@example.test',case when n in (20,25) then 'manager' else 'employee' end from generate_series(20,26) n where n<>24;
insert into public.seats(organization_id,membership_id) select organization_id,id from public.organization_memberships where email like 'training%@example.test';
insert into public.seats(organization_id) values('10000000-0000-0000-0000-000000000020'),('10000000-0000-0000-0000-000000000020');
create function test.training_answers(correct_count integer) returns jsonb language sql as $$
 select jsonb_agg(jsonb_build_object('question_id',id,'option',case when position<=correct_count then (array[2,1,0,2,0])[position] else ((array[2,1,0,2,0])[position]+1)%jsonb_array_length(options) end) order by position) from public.training_questions where course_id='c1000000-0000-4000-8000-000000000001';
$$;
create function test.complete_training(assignment uuid) returns void language plpgsql as $$
declare lesson uuid;
begin
 for lesson in select id from public.training_lessons where course_id='c1000000-0000-4000-8000-000000000001' order by position loop
 perform public.complete_training_lesson(assignment,lesson);
 end loop;
end;
$$;
grant execute on function test.training_answers(integer),test.complete_training(uuid) to authenticated;
